# map each component by 4-connected shapes; count cells, bbox, selected status using hand-coded blocks from demos
D={
'd1':(7,17,[(0,0),(0,11),(1,4),(2,7),(3,1),(3,13),(4,10),(5,6),(5,15)],[(0,0),(0,11),(1,4),(2,7),(5,15)]),
