 # cell grid, block components touch when top-left delta abs<=1 in both axes; neighboring squares can be joined in 4 conn if overlap-edge, i.e delta r=1,c=0 or r=0,c=1
 parent={p:p for p in blocks}
 def find(p):
  while parent[p]!=p: p=parent[p]
  return p
 def union(a,b):
  x,y=find(a),find(b); parent[x]=y
 for i,a in enumerate(blocks):
  for b in blocks[i+1:]:
   if (abs(a[0]-b[0])==1 and a[1]==b[1]) or (abs(a[1]-b[1])==1 and a[0]==b[0]): union(a,b)
 comps={}
 for p in blocks: comps.setdefault(find(p),[]).append(p)
 print('\n',name)
 for co in comps.values():
  print('selected' if any(p in sel for p in co) else 'unchanged',co,'numblocks',len(co),'bounds',(min(p[0] for p in co),max(p[0]+1 for p in co),min(p[1] for p in co),max(p[1]+1 for p in co)))
